//==============================================================================
//  td_osd_overlay.v  --  detection result overlay, styled after the reference
//  ---------------------------------------------------------------------------
//  What is drawn on top of the pixel stream:
//
//    1. a rectangle around every detected target, in the colour of its class
//    2. a label banner on top of a box: "<SHAPE> (<x>,<y>)" in the class colour
//       with white text, for the first three targets
//    3. a translucent status panel in the top-left corner:
//           FPGA OBJECT
//           DETECTION
//           STATUS: RUNNING
//           COUNT: n
//
//  The 5x7 font (td_font5x7) is scaled x2 so a character cell is 16x16 px; one
//  combinational ROM serves both the panel and the labels by muxing its inputs.
//
//  Result bus layout, shared with td_detector.v:
//    [127:0]  BCD nibbles: box i x1 ones at 32i+0 .. thousands at 32i+12,
//             y1 ones at 32i+20, tens 32i+24, hundreds 32i+28
//    [131:128] total count    [147:132] per-class counts
//    [195:148] 8 boxes, 48 bit each: [47] valid [46:45] class
//              [44:34] x1 [33:23] y1 [22:12] x2 [11:1] y2
//    [715:692] 8 shape codes, 3 bit each
//
//  Camera lines are stretched over 720 display lines, hence y << 1 everywhere.
//==============================================================================

module td_osd_overlay #(
    parameter integer IMG_W      = 1280,
    parameter integer IMG_H      = 720,
    parameter integer PANEL_X    = 16,
    parameter integer PANEL_Y    = 16,
    parameter integer PANEL_COLS = 24,   // unused, kept for compatibility
    parameter integer PANEL_ROWS = 7,
    parameter integer BOX_TH     = 2
)(
    input  wire         I_clk,
    input  wire         I_rst_n,
    input  wire         I_vsync,
    input  wire         I_hsync,
    input  wire         I_de,
    input  wire [23:0]  I_data,
    input  wire [715:0] I_res,
    output reg          O_vsync,
    output reg          O_hsync,
    output reg          O_de,
    output reg  [23:0]  O_data,
    output wire [3:0]   O_cnt_total
);

    localparam integer TD_BOX_OFF    = 148;
    localparam integer TD_BOX_STRIDE = 48;
    localparam integer TD_SHAPE_OFF  = 692;

    localparam [23:0] C_RED    = 24'hff3030;
    localparam [23:0] C_GREEN  = 24'h30ff30;
    localparam [23:0] C_BLUE   = 24'h4080ff;
    localparam [23:0] C_YELLOW = 24'hffe820;
    localparam [23:0] C_WHITE  = 24'hffffff;

    localparam integer LBL_CHARS = 17;          // "SQUARE (1234,567)"
    localparam integer LBL_W     = LBL_CHARS * 16;
    localparam integer PANEL_W   = 272;
    localparam integer PANEL_H   = 64;

    assign O_cnt_total = I_res[131:128];

    //--------------------------------------------------------------------------
    //  pixel counters, reset by the vsync edge, one step per active pixel
    //--------------------------------------------------------------------------
    reg [11:0] S_x, S_y;
    reg [11:0] S_x_1d, S_x_2d;
    reg [11:0] S_y_1d, S_y_2d;
    reg        S_de_1d, S_de_2d;
    reg        S_hs_1d, S_hs_2d;
    reg        S_vs_1d, S_vs_2d;
    reg        S_vs_d;
    reg [23:0] S_d_1d, S_d_2d;

    wire S_vs_edge = (I_vsync != S_vs_d);

    always @(posedge I_clk or negedge I_rst_n) begin
        if (!I_rst_n) begin
            S_x    <= 12'd0;
            S_y    <= 12'd0;
            S_vs_d <= 1'b0;
        end
        else begin
            S_vs_d <= I_vsync;
            if (S_vs_edge) begin
                S_x <= 12'd0;
                S_y <= 12'd0;
            end
            else if (I_de) begin
                if (S_x == IMG_W - 1) begin
                    S_x <= 12'd0;
                    S_y <= S_y + 12'd1;
                end
                else begin
                    S_x <= S_x + 12'd1;
                end
            end
        end
    end

    always @(posedge I_clk or negedge I_rst_n) begin
        if (!I_rst_n) begin
            S_x_1d <= 12'd0;  S_x_2d <= 12'd0;
            S_y_1d <= 12'd0;  S_y_2d <= 12'd0;
            S_de_1d <= 1'b0;  S_de_2d <= 1'b0;
            S_hs_1d <= 1'b0;  S_hs_2d <= 1'b0;
            S_vs_1d <= 1'b0;  S_vs_2d <= 1'b0;
            S_d_1d  <= 24'd0; S_d_2d  <= 24'd0;
        end
        else begin
            S_x_1d <= S_x;      S_x_2d <= S_x_1d;
            S_y_1d <= S_y;      S_y_2d <= S_y_1d;
            S_de_1d <= I_de;    S_de_2d <= S_de_1d;
            S_hs_1d <= I_hsync; S_hs_2d <= S_hs_1d;
            S_vs_1d <= I_vsync; S_vs_2d <= S_vs_1d;
            S_d_1d  <= I_data;  S_d_2d  <= S_d_1d;
        end
    end

    //--------------------------------------------------------------------------
    //  helpers
    //--------------------------------------------------------------------------
    function [7:0] F_dig;            // nibble -> ASCII, blank when suppressed
        input [3:0] d;
        input       en;
        begin
            F_dig = en ? (8'h30 + {4'd0, d}) : 8'h20;
        end
    endfunction

    function [23:0] F_color;
        input [1:0] c;
        begin
            case (c)
                2'd0:    F_color = C_RED;
                2'd1:    F_color = C_GREEN;
                2'd2:    F_color = C_BLUE;
                default: F_color = C_YELLOW;
            endcase
        end
    endfunction

    function [47:0] F_shape_txt;     // six printable characters
        input [2:0] s;
        begin
            case (s)
                3'd1:    F_shape_txt = "SQUARE";
                3'd2:    F_shape_txt = "CIRCLE";
                3'd3:    F_shape_txt = "TRIANG";
                3'd4:    F_shape_txt = "RECT-H";
                3'd5:    F_shape_txt = "RECT-V";
                default: F_shape_txt = "UNKNWN";
            endcase
        end
    endfunction

    // pick the k-th character out of a 17-character string packed MSB first
    function [7:0] F_pick;
        input [135:0] s;
        input [4:0]   k;
        begin
            case (k)
                5'd0:  F_pick = s[135:128];
                5'd1:  F_pick = s[127:120];
                5'd2:  F_pick = s[119:112];
                5'd3:  F_pick = s[111:104];
                5'd4:  F_pick = s[103:96];
                5'd5:  F_pick = s[95:88];
                5'd6:  F_pick = s[87:80];
                5'd7:  F_pick = s[79:72];
                5'd8:  F_pick = s[71:64];
                5'd9:  F_pick = s[63:56];
                5'd10: F_pick = s[55:48];
                5'd11: F_pick = s[47:40];
                5'd12: F_pick = s[39:32];
                5'd13: F_pick = s[31:24];
                5'd14: F_pick = s[23:16];
                5'd15: F_pick = s[15:8];
                5'd16: F_pick = s[7:0];
                default: F_pick = 8'h20;
            endcase
        end
    endfunction

    //--------------------------------------------------------------------------
    //  box unpack
    //--------------------------------------------------------------------------
    wire        W_bv  [0:7];
    wire [1:0]  W_bc  [0:7];
    wire [10:0] W_bx1 [0:7];
    wire [10:0] W_by1 [0:7];
    wire [10:0] W_bx2 [0:7];
    wire [10:0] W_by2 [0:7];
    wire [2:0]  W_bs  [0:7];

    genvar gi;
    generate
        for (gi = 0; gi < 8; gi = gi + 1) begin : g_box
            assign W_bv[gi]  = I_res[TD_BOX_OFF + TD_BOX_STRIDE*gi + 47];
            assign W_bc[gi]  = I_res[TD_BOX_OFF + TD_BOX_STRIDE*gi + 46 -: 2];
            assign W_bx1[gi] = I_res[TD_BOX_OFF + TD_BOX_STRIDE*gi + 44 -: 11];
            assign W_by1[gi] = I_res[TD_BOX_OFF + TD_BOX_STRIDE*gi + 33 -: 11];
            assign W_bx2[gi] = I_res[TD_BOX_OFF + TD_BOX_STRIDE*gi + 22 -: 11];
            assign W_by2[gi] = I_res[TD_BOX_OFF + TD_BOX_STRIDE*gi + 11 -: 11];
            assign W_bs[gi]  = I_res[TD_SHAPE_OFF + 3*gi +: 3];
        end
    endgenerate

    //--------------------------------------------------------------------------
    //  rectangles (all eight), drawn in the class colour
    //--------------------------------------------------------------------------
    reg        S_box_hit;
    reg [23:0] S_box_color;
    reg [10:0] T_x1, T_x2, T_y1, T_y2;
    reg        T_inx, T_iny, T_edge;
    integer bi;

    always @(*) begin
        S_box_hit   = 1'b0;
        S_box_color = 24'd0;
        for (bi = 7; bi >= 0; bi = bi - 1) begin
            T_x1 = W_bx1[bi];
            T_x2 = W_bx2[bi];
            T_y1 = W_by1[bi];               // 1:1, the stream is 720 lines
            T_y2 = W_by2[bi];
            T_inx = (S_x_2d >= {1'b0, T_x1}) && (S_x_2d <= {1'b0, T_x2});
            T_iny = (S_y_2d >= {1'b0, T_y1}) && (S_y_2d <= {1'b0, T_y2});
            T_edge = T_inx && T_iny &&
                     (((S_x_2d - {1'b0, T_x1}) < BOX_TH) ||
                      (({1'b0, T_x2} - S_x_2d) < BOX_TH) ||
                      ((S_y_2d - {1'b0, T_y1}) < BOX_TH) ||
                      (({1'b0, T_y2} - S_y_2d) < BOX_TH));
            if (W_bv[bi] && (T_x2 > T_x1) && (T_y2 > T_y1) && T_edge) begin
                S_box_hit   = 1'b1;
                S_box_color = F_color(W_bc[bi]);
            end
        end
    end

    //--------------------------------------------------------------------------
    //  label banner + text, first three boxes
    //--------------------------------------------------------------------------
    wire [7:0]  L_ch   [0:2];
    wire [2:0]  L_row  [0:2];
    wire [2:0]  L_col  [0:2];
    wire        L_hit  [0:2];
    wire [23:0] L_color[0:2];

    genvar li;
    generate
        for (li = 0; li < 3; li = li + 1) begin : g_lbl
            wire [10:0] L_bx = W_bx1[li];
            wire [10:0] L_by = W_by1[li];

            // keep the banner on screen
            wire [11:0] L_lx = (L_bx > (IMG_W - LBL_W)) ? (IMG_W - LBL_W) : L_bx;
            wire [11:0] L_ly = (L_by >= 12'd18) ? (L_by - 12'd18) : (L_by + 12'd2);

            wire [11:0] L_dx  = S_x_2d - L_lx;
            wire [11:0] L_dy  = S_y_2d - L_ly;

            // digits of x1 and y1, leading zeros blanked
            wire [3:0] X3 = I_res[32*li + 12 +: 4];
            wire [3:0] X2 = I_res[32*li +  8 +: 4];
            wire [3:0] X1 = I_res[32*li +  4 +: 4];
            wire [3:0] X0 = I_res[32*li +  0 +: 4];
            wire [3:0] Y2 = I_res[32*li + 24 +: 4];
            wire [3:0] Y1 = I_res[32*li + 20 +: 4];
            wire [3:0] Y0 = I_res[32*li + 16 +: 4];

            wire [135:0] L_str = {
                F_shape_txt(W_bs[li]), 8'h20, 8'h28,
                F_dig(X3, (X3 != 4'd0)),
                F_dig(X2, ((X3 | X2) != 4'd0)),
                F_dig(X1, ((X3 | X2 | X1) != 4'd0)),
                F_dig(X0, 1'b1),
                8'h2c,
                F_dig(Y2, (Y2 != 4'd0)),
                F_dig(Y1, ((Y2 | Y1) != 4'd0)),
                F_dig(Y0, 1'b1),
                8'h29
            };

            assign L_hit  [li] = W_bv[li] &&
                                 (S_x_2d >= L_lx) && (L_dx < LBL_W) &&
                                 (S_y_2d >= L_ly) && (L_dy < 12'd16);
            assign L_ch   [li] = F_pick(L_str, L_dx[8:4]);
            assign L_row  [li] = L_dy[3:1];
            assign L_col  [li] = L_dx[3:1];
            assign L_color[li] = F_color(W_bc[li]);
        end
    endgenerate

    //--------------------------------------------------------------------------
    //  status panel
    //--------------------------------------------------------------------------
    wire [3:0] S_cnt     = I_res[131:128];
    wire       S_cnt_ten = (S_cnt >= 4'd10);
    wire [3:0] S_cnt_one = S_cnt_ten ? (S_cnt - 4'd10) : S_cnt;

    wire S_in_panel = (S_x_2d >= PANEL_X) && (S_x_2d < PANEL_X + PANEL_W) &&
                      (S_y_2d >= PANEL_Y) && (S_y_2d < PANEL_Y + PANEL_H);

    wire [11:0] S_pdx  = S_x_2d - PANEL_X;
    wire [11:0] S_pdy  = S_y_2d - PANEL_Y;
    wire [1:0]  S_pln  = S_pdy[5:4];        // one 16 px line per entry
    wire [4:0]  S_pcl  = S_pdx[8:4];
    wire [2:0]  S_pcol = S_pdx[3:1];
    wire [2:0]  S_prow = S_pdy[3:1];

    reg [7:0] S_pchar;
    always @(*) begin
        S_pchar = 8'h20;
        case (S_pln)
        2'd0: case (S_pcl)                  // FPGA OBJECT
            5'd0: S_pchar = "F";  5'd1: S_pchar = "P";  5'd2: S_pchar = "G";
            5'd3: S_pchar = "A";  5'd4: S_pchar = " ";  5'd5: S_pchar = "O";
            5'd6: S_pchar = "B";  5'd7: S_pchar = "J";  5'd8: S_pchar = "E";
            5'd9: S_pchar = "C";  5'd10: S_pchar = "T";
            default: S_pchar = 8'h20;
            endcase
        2'd1: case (S_pcl)                  // DETECTION
            5'd0: S_pchar = "D";  5'd1: S_pchar = "E";  5'd2: S_pchar = "T";
            5'd3: S_pchar = "E";  5'd4: S_pchar = "C";  5'd5: S_pchar = "T";
            5'd6: S_pchar = "I";  5'd7: S_pchar = "O";  5'd8: S_pchar = "N";
            default: S_pchar = 8'h20;
            endcase
        2'd2: case (S_pcl)                  // STATUS: RUNNING
            5'd0: S_pchar = "S";  5'd1: S_pchar = "T";  5'd2: S_pchar = "A";
            5'd3: S_pchar = "T";  5'd4: S_pchar = "U";  5'd5: S_pchar = "S";
            5'd6: S_pchar = ":";  5'd7: S_pchar = " ";  5'd8: S_pchar = "R";
            5'd9: S_pchar = "U";  5'd10: S_pchar = "N"; 5'd11: S_pchar = "N";
            5'd12: S_pchar = "I"; 5'd13: S_pchar = "N"; 5'd14: S_pchar = "G";
            default: S_pchar = 8'h20;
            endcase
        default: case (S_pcl)               // COUNT: nn
            5'd0: S_pchar = "C";  5'd1: S_pchar = "O";  5'd2: S_pchar = "U";
            5'd3: S_pchar = "N";  5'd4: S_pchar = "T";  5'd5: S_pchar = ":";
            5'd6: S_pchar = S_cnt_ten ? (8'h30 + {4'd0, S_cnt_ten}) : 8'h20;
            5'd7: S_pchar = 8'h30 + {4'd0, S_cnt_one};
            default: S_pchar = 8'h20;
            endcase
        endcase
    end

    wire [23:0] S_p_txt_color = (S_pln == 2'd2 && S_pcl >= 5'd8) ? C_GREEN : C_WHITE;
    // 50 % darkening keeps the panel readable without hiding the video
    wire [23:0] S_p_bg = {1'b0, S_d_2d[23:17], 1'b0, S_d_2d[15:9], 1'b0, S_d_2d[7:1]};

    //--------------------------------------------------------------------------
    //  one shared font ROM, inputs muxed by priority
    //--------------------------------------------------------------------------
    wire [7:0] S_f_char = S_in_panel ? S_pchar   :
                          L_hit[0]   ? L_ch[0]   :
                          L_hit[1]   ? L_ch[1]   :
                          L_hit[2]   ? L_ch[2]   : 8'h20;
    wire [2:0] S_f_row  = S_in_panel ? S_prow    :
                          L_hit[0]   ? L_row[0]  :
                          L_hit[1]   ? L_row[1]  :
                          L_hit[2]   ? L_row[2]  : 3'd0;
    wire [2:0] S_f_col  = S_in_panel ? S_pcol    :
                          L_hit[0]   ? L_col[0]  :
                          L_hit[1]   ? L_col[1]  :
                          L_hit[2]   ? L_col[2]  : 3'd0;

    wire [4:0] W_font_pix;
    td_font5x7 u_font (
        .I_char(S_f_char),
        .I_row (S_f_row),
        .O_pix (W_font_pix)
    );

    wire S_f_on = (S_f_col < 3'd5) && W_font_pix[4 - S_f_col];

    //--------------------------------------------------------------------------
    //  compositing
    //--------------------------------------------------------------------------
    always @(posedge I_clk or negedge I_rst_n) begin
        if (!I_rst_n) begin
            O_vsync <= 1'b0;
            O_hsync <= 1'b0;
            O_de    <= 1'b0;
            O_data  <= 24'd0;
        end
        else begin
            O_vsync <= S_vs_2d;
            O_hsync <= S_hs_2d;
            O_de    <= S_de_2d;

            if (S_in_panel)
                O_data <= S_f_on ? S_p_txt_color : S_p_bg;
            else if (L_hit[0])
                O_data <= S_f_on ? C_WHITE : L_color[0];
            else if (L_hit[1])
                O_data <= S_f_on ? C_WHITE : L_color[1];
            else if (L_hit[2])
                O_data <= S_f_on ? C_WHITE : L_color[2];
            else if (S_box_hit)
                O_data <= S_box_color;
            else
                O_data <= S_d_2d;
        end
    end

endmodule
